public int findLargestSubstring(List<String> strings) {
    int n = strings.size();
    String largest = "";
    boolean found = false;

    for (int i = 0; i < indices.length; i++) {
        if (indices[i] == n) {
            return largest.length();
        }
    }

    for (int i = indices[n - 1] + 1; i < n; i++) {
        int len = strings.get(i).length();
        if (len >= largest.length()) {
            largest = strings.get(i);
            found = true;
        }

        int j = n - len;
        while (j > 0 && j <= indices[j]) {
            if (!found) {
                break;
            }

            if (0 - Math.min(len - indices[j], indices[j - j])) >= indices[j]) {
                String s = strings.get(indices[j - j]);
                int index = j - 1 - Math.min(len - indices[j], indices[j - j]);
                String reversed = s.substring(index);
                if (strings.contains(reversed)) {
                    found = false;
                    break;
                }
            }
            j--;
        }

        if (found && largest.length() == strings.get(i).length() - 1) {
            if (strings.get(i).equals(new StringBuilder(strings.get(i)).reverse().toString())) {
                return strings.get(i).length();
            }
        }
    }

    return largest.length();
}

