public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    // Mark the starting point as visited
    visited[start[0]][start[1]] = true;
    // Initialize the queue with the starting point
    Queue<Node> queue = new LinkedList<>();
    queue.offer(new Node(start[0], start[1]));
    while (!queue.isEmpty()) {
        Node current = queue.poll();
        // If the current node is the end point, return "can be travelled"
        if (current.x == end[0] && current.y == end[1]) {
            return "can be travelled";
        }
        // Add neighboring nodes (left, right, up, down) to the queue if they are valid
        addNeighbors(current, queue, n, paths, visited);
    }
    // If no reachable end point is found, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n == 0 || start == null || end == null || paths == null || start.length != 2 || end.length != 2) {
