    int count = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                count++;
                break; // Break after finding one common letter
            }
        }
    }
    double approximateValue = (double) count / (word1.length() + word2.length() - count);
    String reducedFraction = Fraction.toReducedFraction(approximateValue);
    return "appx(" + word1 + ", " + word2 + ") = " + reducedFraction;
}

