    int length1 = word1.length();
    int length2 = word2.length();

    for (int i = 0; i < length1 && i < length2; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    int least = Math.min(length1, length2);
    double reducedFraction = ((double) commonLetters) / least;

    // Format the reduced fraction as a string
    int numerator = (int) (reducedFraction * 100); // Convert to hundredths
    int denominator =least * 100;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

