public static String convertDatesToWeekdays(String date) {
        // Parse the date into day, month, and year components
        int day = Integer.parseInt(date.split(" ")[1]);
        int month = Integer.parseInt(date.split(" ")[0]);
        int year = Integer.parseInt(date.split(" ")[2]);

        // Create a Calendar instance and set the date
        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);

        // Get the name of the weekday
        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        String weekday = weekdays[calendar.get(java.util.Calendar.DAY_OF_WEEK) - 1];

        // Format the result string
        return date + " is a " + weekday;
    }

