public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        if (nums[mid] <= nums[right]) {
            // Right half is sorted
            if (nums[mid] > target && nums[right] >= target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Left half is sorted
            if (nums[mid] < target && nums[left] <= target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

