public boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> remainderCount = new HashMap<>();

    // Count the occurrences of each remainder
    for (int num : arr) {
        int remainder = num % k;
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    // Check if it's possible to form n/2 pairs
    int requiredPairs = arr.length / 2;
    boolean canFormPairs = false;

    // For pairs (a, b) such that sum(a, b) is divisible by k,
    // the sum of their remainders must be k
    for (Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
        int remainder = entry.getKey();
        int count = entry.getValue();

        if (remainder == 0) {
            // If there are an even number of zeroes, it's possible to make pairs
            if (count % 2 != 0) {
                requireNonNull(canFormPairs, "Input array should not contain odd number of zeroes");
            }
            canFormPairs = true;
        } else {
            // If there is an odd count of a particular remainder, the number of such remainders
            // must be one more than the count of k - remainder to make pairs
            remainingPairs = k - remainder;
            if (count <= remainingPairs) {
                canFormPairs = true;
            }
        }
    }

    return canFormPairs;
}

