    Set<Integer> visited = new HashSet<>();
    queue.add(0);
    visited.add(0);

    int totalTime = 0;
    int lastNode = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();

        if (hasApple[node]) {
            totalTime += 2; // Time for walking to the current node and back
        }

        int distance = 0;

        for (int nextNode : graph[node]) {
            if (!visited.contains(nextNode)) {
                visited.add(nextNode);
                distance++;
                queue.add(nextNode);

                // If next node has an apple, increase totalTime by time to get back to the parent
                if (hasApple[nextNode]) {
                    totalTime += distance + 2; // Time for walking to the next node, back to the parent, and back to the current node
                }
                lastNode = nextNode;
            }
        }
    }

    return totalTime;
}

