public String sortString(String s) {
    char[] chars = s.toCharArray();
    char[] sortedChars = new char[s.length()];
    int index = 0;

    while (index < chars.length) {
        // Pick the smallest character
        char min = 'z' + 1;
        for (char ch : chars) {
            if (ch < min && ch != sortedChars[index - 1]) {
                min = ch;
            }
        }
        sortedChars[index++] = min;

        // Find the next smallest character
        int nextMinIndex = index;
        for (int i = index; i < chars.length; i++) {
            if (chars[i] > min && chars[i] != sortedChars[index - 1]) {
                min = chars[i];
                nextMinIndex = i;
            }
        }
        if (nextMinIndex != index) {
            char temp = sortedChars[index];
            sortedChars[index] = sortedChars[nextMinIndex];
            sortedChars[nextMinIndex] = temp;
        }

        // Pick the largest character
        char max = 'a';
        for (char ch : chars) {
            if (ch > max && ch != sortedChars[index - 1]) {
                max = ch;
            }
        }
        sortedChars[index++] = max;

        // Find the next largest character
        int nextMaxIndex = index;
        for (int i = index; i < chars.length; i++) {
            if (chars[i] < max && chars[i] != sortedChars[index - 1]) {
                max = chars[i];
                nextMaxIndex = i;
            }
        }
        if (nextMaxIndex != index) {
            char temp = sortedChars[index];
            sortedChars[index] = sortedChars[nextMaxIndex];
            sortedChars[nextMaxIndex] = temp;
        }
    }

    return new String(sortedChars);
}

