    // Populate minHeap with characters from s
    for (char ch : s.toCharArray()) {
        minHeap.offer(ch);
    }

    // Populate maxHeap with characters from s
    for (char ch : s.toCharArray()) {
        maxHeap.offer(ch);
    }

    StringBuilder result = new StringBuilder();

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
