public String sortString(String s) {
    if(s.length() == 0) {
        return "";
    }

    PriorityQueue<Character> priorityQueueAsc = new PriorityQueue<>();
    PriorityQueue<Character> priorityQueueDesc = new PriorityQueue<>(Comparator.reverseOrder());

    for(int i = 0; i < s.length(); i++) {
        priorityQueueAsc.add(s.charAt(i));
        priorityQueueDesc.add(s.charAt(i));
    }

    StringBuilder result = new StringBuilder();
    int lastAdded = 0;

    while(!priorityQueueAsc.isEmpty() || !priorityQueueDesc.isEmpty()) {
        char c;
        if(priorityQueueAsc.isEmpty()) {
            c = priorityQueueDesc.poll();
        } else if(priorityQueueDesc.isEmpty()) {
            c = priorityQueueAsc.poll();
        } else if(lastAdded == priorityQueueAsc.peek().charValue()) {
            c = priorityQueueAsc.poll();
        } else if(lastAdded == priorityQueueDesc.peek().charValue()) {
            c = priorityQueueDesc.poll();
        } else {
            if(priorityQueueAsc.peek().charValue() > priorityQueueDesc.peek().charValue()) {
                c = priorityQueueAsc.poll();
            } else {
                c = priorityQueueDesc.poll();
            }
        }

        result.append(c);
        lastAdded = c;
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    boolean[] usedChars = new boolean[256];
    int smallest = 'z';
    int largest = 'a';
    int smallestIdx = s.length();
    int largestIdx = s.length();
    while (true) {
        // Find the smallest character that has not been used and is less than or equal to the largest used character
        smallest = 'z';
        smallestIdx = s.length();
        for (char c : s.toCharArray()) {
            if (!usedChars[c] && c <= largest && smallest > c) {
                smallest = c;
                smallestIdx = s.indexOf(c);
            }
        }
        // Append the smallest character if found
        if (smallestIdx != s.length()) {
            result.append(smallest);
            usedChars[smallest] = true;
            largest = Math.max(largest, smallest);
        } else {
            // Find the largest character that has not been used and is greater than the smallest used character
            largest = 'a';
            largestIdx = s.length();
            for (char c : s.toCharArray()) {
                if (!usedChars[c] && c >= smallest && largest < c) {
                    largest = c;
                    largestIdx = s.indexOf(c);
                }
            }
            // Append the largest character if found
            if (largestIdx != s.length()) {
                result.append(largest);
                usedChars[largest] = true;
                smallest = Math.min(smallest, largest);
            } else {
                break;
            }
        }
    }
    return result.toString();
}

