public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[]	dp = new int[n];

    if (n <= 1) {
        return cost[0];
    }

    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return dp[n - 1];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int oneStep = cost[0], twoStep =_cost[1], step;

    for (int i = 2; i < n; i++) {
        step = cost[i] + Math.min(oneStep, twoStep);
        oneStep = twoStep;
        twoStep = step;
    }

    return Math.min(oneStep, twoStep);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }

    // Initialize a length n array to store the minimum cost to reach each step
    int[] dp = new int[n];

    // Base case: The minimum cost to reach the last step is the last step's cost
    dp[n - 1] = cost[n - 1];

    // Base case: The minimum cost to reach the second last step is the second last step's cost
    dp[n - 2] = cost[n - 2];

    // Fill the dp array from the third last step to the first step
    for (int i = n - 3; i >= 0; i--) {
        // The minimum cost to reach step i is the cost of step i + the minimum cost to reach the step ahead or the step two steps ahead
        dp[i] = cost[i] + Math.min(dp[i + 1], dp[i + 2]);
    }

    // The minimum cost to reach the first step is the minimum cost to reach the second step
    return Math.min(dp[0], dp[1]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // If there are 1 or 2 steps, the cost is straightforward to compute
    if (n <= 2) {
        return cost[0] + (n == 2 ? cost[2] : 0);
    }
    // Set up an array to store the minimum cost to reach each step
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    // Fill the dp array to find the minimum cost to reach each step
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }
    // The minimum cost to reach the top is the last element in the dp array
    return dp[n-1];
}

