public boolean hasAllCodes(String s, int k) {
    Map<String, Integer> count = new HashMap<>();
    for (int i = 0; i + k <= s.length(); i++) {
        String sub = s.substring(i, i + k);
        count.put(sub, count.getOrDefault(sub, 0) + 1);
        if (count.size() > k) {
            return false;
        }
    }
    return count.size() == k;
}

public boolean hasAllCodes(String s, int k) {
    int substringCount = (int) Math.pow(2, k);
    var uniqueSubstrings = new HashSet<String>();

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        if (!uniqueSubstrings.add(substring)) {
            return false;
        }
    }

    return uniqueSubstrings.size() == substringCount;
}

public boolean hasAllCodes(String s, int k) {
        // Create a set to store all possible binary strings of length k
        Set<String> allCodes = new HashSet<>();

        // Iterate over the string and generate all possible binary strings of length k
        for (int i = 0; i <= s.length() - k; i++) {
            allCodes.add(s.substring(i, i + k));
        }

        // Check if the length of the set is equal to 2^k
        return allCodes.size() == 1 << k;
    }

