public int minOperations(int n) {
    int totalIncrease = (n - 1) * 2;
    return (totalIncrease + 1) / 2;
}

public int minOperations(int n) {
    int operations = 0;
    int target = n % 2 == 0 ? n // If n is even, target is n itself
                              : n; // If n is odd, target is n - 1
    for (int i = 0; i < n && target > 0; i++) {
        operations += n / 2 - (i % 2 == 0 ? i / 2 : (i + 1) / 2);
        target--;
    }
    return operations;
}

public int minOperations(int n) {
    int left = 1;
    int right = n;
    int operations = 0;

    while (left < right) {
        operations += right - right / 2;
        int mid = left + (right - left) / 2;
        operations += mid - left;
        left = mid + 1;
    }

    return operations;
}

public int minOperations(int n) {
    int totalSum = n * (2 * n + 1) / 2;
    int minVal = 1;
    while (maxVal < minVal) {
        int middle = (maxVal + minVal) / 2;
        int currentSum = middle + ((middle + 1) * middle) / 2;
        if (currentSum < totalSum) {
            minVal = middle + 1;
        } else {
            maxVal = middle;
        }
    }
    return totalSum - (minVal + ((minVal + 1) * minVal) / 2);
}

public int minOperations(int n) {
        int operations = 0;
        int targetValue = (n * 2 + 1) / 2; // Calculate the target value for all elements to be equal

        // Calculate the total difference from the target value for all elements
        for (int i = 0; i < n; i++) {
            int difference = Math.abs((2 * i + 1) - targetValue);
            operations += difference; // Add the absolute difference to the total operations
        }

        return operations;
    }

