public int maxAbsoluteSum(int[] nums) {
    int posSum = 0, negSum = 0, maxSum = 0;
    for (int num : nums) {
        posSum = Math.max(num, posSum + num);
        negSum = Math.max(num, negSum + num);
        maxSum = Math.max(maxSum, Math.max(posSum, -negSum));
    }
    return maxSum;
}

public int maxAbsoluteSum(int[] nums) {
    int max = 0, min = 0, curMax = 0, curMin = 0;
    for (int num : nums) {
        curMax = Math.max(num, curMax + num);
        curMin = Math.min(num, curMin + num);
        max = Math.max(max, curMax);
        min = Math.min(min, curMin);
    }
    return max - min;
}

