}

public int maxAbsoluteSum(int[] nums) {
    int max = Integer.MIN_VALUE;
    int min = Integer.MAX_VALUE;

    for (int num : nums) {
        if (num > max) {
            max = num;
        } else if (num < min) {
            min = num;
        }

        max = Math.max(max, num * (-1));
        min = Math.min(min, num * (-1));
    }

    return Math.max(max, Math.abs(min));
}

