        currentMin = Math.min(num, currentMin + num);
        maxSum = Math.max(maxSum, currentMax);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibs.add(a);
        int next = a + b;
        a = b;
        b = next;
    }

    Collections.reverse(fibs);
    int count = 0;
    for (int fib : fibs) {
        if (k >= fib) {
            k -= fib;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibonacciNumbers = new ArrayList<>();
    int a = 0, b = 1, c = 0;
    while (c <= k) {
        fibonacciNumbers.add(c);
        if (c <= 1) {
            a = 1;
            b = 1;
        } else {
            c = a + b;
            a = b;
            b = c;
        }
    }

    int count = 0;
    for (int i = fibonacciNumbers.size() - 1; i >= 0; i--) {
        while (k >= fibonacciNumbers.get(i)) {
            k -= fibonacciNumbers.get(i);
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    int n = 0, t = 1;
    while (t <= k) {
        t += n;
        n = t - n;
    }
    int ans = 0;
    while (k > 0) {
        if (t > k) {
            t -= n;
        } else {
            ans++;
            k -= t;
            t = n;
        }
    }
    return ans;
}

public int findMinFibonacciNumbers(int k) {
    // Function to find the next Fibonacci number
    int nextFib = new int[2];
    nextFib[0] = 1;

    while (nextFib[0] + nextFib[1] <= k) {
        nextFib[0] = nextFib[1];
        nextFib[1] = nextFib[0] + nextFib[1];
    }

    // Backtracking to find the minimum numbers
    return findMinFibonacciNumbers(k, nextFib, new ArrayList<>(), 0);
}

public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;

    Set<Integer> fibSet = new HashSet<>();
    int a = 0, b = 1;
    while (b <= k) {
        fibSet.add(b);
        int temp = a + b;
        a = b;
        b = temp;
    }

    int result = 0;
    while (!fibSet.isEmpty()) {
        if (k >= fibSet.iterator().next()) {
            k -= fibSet.iterator().next();
            result++;
        } else {
            fibSet.remove(fibSet.iterator().next());
        }
    }

    return result;
}

