public String makeGood(String s) {
    StringBuilder sb = new StringBuilder(s);
    int i = 0, j = 1;
    while (j < sb.length()) {
        if (sb.charAt(i) == sb.charAt(j) + 32 || sb.charAt(i) + 32 == sb.charAt(j)) {
            sb.deleteCharAt(j);
            sb.deleteCharAt(i);
            i = Math.min(i, j - 2); // Adjust i if necessary
        } else {
            i++;
            j++;
        }
    }
    return sb.toString();
}

public String makeGood(String s) {
    Deque<Character> stack = new LinkedList<>();
    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.getLast() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }
    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.pop());
    }
    return sb.reverse().toString();
}

