public String getSmallestString(int n, int k) {
    char[] smallestString = new char[n];
    smallestString[n - 1] = 'z';
    k += n - 1;
    for (int i = n - 2; i >= 0; i--) {
        if (k == 0) {
            while (i >= 0 && smallestString[i] == 'z') {
                smallestString[i] = 'a';
                i--;
            }
        } else {
            smallestString[i] = (char) ('z' - k % 26);
            k -= k % 26;
        }
    }
    return new String(smallestString);
