public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    Deque<Integer> queue = new ArrayDeque<>();
    queue.add(0);
    queue.add(1);

    while (!queue.isEmpty()) {
        Integer num = queue.poll();
        if (num >= low && num <= high) {
            steppingNumbers.add(num);
        }

        int lastDigit = num % 10;
        if (lastDigit == 0) {
            queue.add(num * 10 + 1);
        } else if (lastDigit == 9) {
            queue.add(num * 10 + 8);
        } else {
            queue.add(num * 10 + lastDigit - 1);
            queue.add(num * 10 + lastDigit + 1);
        }
    }

    steppingNumbers.sort(Integer::compare);
    return steppingNumbers;
}

