        HashSet<Integer> visited = new HashSet<>();

        // Pre compute and add all 1-digit stepping numbers
        for (int i = 0; i <= 9; i++) {
            visited.add(i);
        }

        while (!visited.isEmpty()) {
            int current = visited.iterator().next();
            visited.remove(current);

            if (current >= low && current <= high) {
                steppingNumbers.add(current);
            }

            // Generate all possible numbers by adding 1 or 0 to the last digit of current
            int next1 = current * 10 + 1;
            int next2 = current * 10 + 0;

            if (next1 <= high) {
                visited.add(next1);
            }
            if (next2 <= high && Math.abs(next1 - next2) == 1) {
                visited.add(next2);
            }
        }

        steppingNumbers.sort(null);
        return steppingNumbers;
    }

