public static int countDigitOne(int n) {
    if (n < 1) {
        return 0;
    }

    int count = 0;
    int placeValue = 1;
    int high = n / placeValue;

    while (high > 0) {
        int low = n % placeValue;
        int ten = placeValue * 10;

        // Calculate the count of digits 1 in the们 current place
        int countOnes = (int) ((high + 8) / 10) * placeValue + Math.min(high % 10, 1) * placeValue;

        // Calculate the count of digits 1 in the higher place
        if (low == 0) {
            countOnes += (n - high * placeValue) * placeValue;
        } else {
            countOnes += (high + 1) * placeValue + Math.min(low, 1) * placeValue;
        }

        count += countOnes;
        placeValue *= 10;
        high /= 10;
    }

    return count;
}

