public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1 + Math.max(Math.min(dp[i - 1][j], dp[i - 1][j - 1], dp[i][j - 1]), dp[i + 1][j], dp[i + 1][j + 1], dp[i][j + 1]);
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
