    int[][] directions = {
        {1, 0}, // right
        {0, 1}, // down
        {1, 1}, // diagonal down
        {1, -1} // anti-diagonal down
    };

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : directions) {
                    int len = 1;
                    int x = i + dir[0];
                    int y = j + dir[1];
                    while (x >= 0 && y >= 0 && x < mat.length && y < mat[0].length && mat[x][y] == 1) {
                        len++;
                        x += dir[0];
                        y += dir[1];
                    }
                    maxLen = Math.max(maxLen, len);
                }
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    int max = 0;
    int rowLen = mat.length;
    int colLen = mat[0].length;

    // Process verticle
    for (int row = 0; row < rowLen; row++) {
        int localMax = 0, flat = 0;
        for (int col = 0; col < colLen; col++) {
            if (mat[row][col] == 1) {
                flat++;
                localMax = Math.max(flat, localMax);
            } else {
                flat = 0;
            }
            max = Math.max(localMax, max);
        }
    }

    // Process horizontal
    for (int col = 0; col < colLen; col++) {
        int localMax = 0, flat = 0;
        for (int row = 0; row < rowLen; row++) {
            if (mat[row][col] == 1) {
                flat++;
                localMax = Math.max(flat, localMax);
            } else {
                flat = 0;
            }
            max = Math.max(localMax, max);
        }
    }

    // Process oblique (45°)
    for (int row = 0; row + 1 < rowLen && col + 1 < colLen; row++, col++) {
        int localMax = 0, flat = 0;
        for (; row < rowLen && col < colLen; row++, col++) {
            if (mat[row][col] == 1) {
                flat++;
                localMax = Math.max(flat, localMax);
            } else {
                flat = 0;
            }
            max = Math.max(localMax, max);
        }
    }

    // Process anti-oblique (135°)
    for (int row = 0; row + 1 < rowLen && col >= 1; row++, col--) {
        int localMax = 0, flat = 0;
        for (; row < rowLen && col >= 0; row++, col--) {
            if (mat[row][col] == 1) {
                flat++;
                localMax = Math.max(flat, localMax);
            } else {
                flat = 0;
            }
            max = Math.max(localMax, max);
        }
    }

    return max;
}

public static int longestLine(int[][] mat) {
