    int maxLength = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                // Check horizontal, vertical, and 45-degree directions
                for (int k = 1; i + k < rows && j + k < cols && mat[i + k][j + k] == 1; k++) {
                    currentLength++;
                }
                for (int k = 1; i - k >= 0 && j + k < cols && mat[i - k][j + k] == 1; k++) {
                    currentLength++;
                }
                for (int k = 1; i + k < rows && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
                    currentLength++;
                }
                for (int k = 1; i - k >= 0 && j - k >= 0 && mat[i - k][j - k] == 1; k++) {
