}

public static int longestLine(int[][] mat) {
    int count = 0, newCount = 0;
    int up = 0, down = 0, left = 0, right = 0;

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                newCount = 2;
                if (i - 1 >= 0 && mat[i - 1][j] == 1) {
                    newCount = Math.max(newCount, 1 + up);
                    up++;
                }
                if (i + 1 < mat.length && mat[i + 1][j] == 1) {
                    newCount = Math.max(newCount, 1 + down);
                    down++;
                }
                if (j - 1 >= 0 && mat[i][j - 1] == 1) {
                    newCount = Math.max(newCount, 1 + left);
                    left++;
                }
                if (j + 1 < mat[0].length && mat[i][j + 1] == 1) {
                    newCount = Math.max(newCount, 1 + right);
                    right++;
                }
            } else {
                count = Math.max(count, newCount);
                newCount = 0;
                up = 0;
                down = 0;
                left = 0;
                right = 0;
            }
        }
        count = Math.max(count, newCount);
    }

    return count;
}

public static String addThousandSeparator(int n) {
