    while (remainingDigits > 0) {
        int digitCount = Math.min(3, remainingDigits);
        int truncated = remainingDigits % 3 == 0 ? remainingDigits : remainingDigits % 3;
        result.insert(0, truncated);
        for (int i = 0; i < digitCount - 1; i++) {
            result.insert(0, '.');
        }
        remainingDigits /= 10;
    }

    return result.toString();
}

