            sortedA[i], sortedA[j] = sortedA[j], sortedA[i];
            previousSquares.add(sortedA[i]);
            visited.add(square);
            result += squarePermutations(sortedA);
            sortedA[i], sortedA[j] = sortedA[j], sortedA[i];
            previousSquares.remove(square);
            visited.remove(square);
        }
    }

    return result;
}

