        result[ix] = mat[x][y];
        int newX = x + dx[dir];
        int newY = y + dy[dir];
        if (newX < 0 || newX >= rows || newY < 0 || newY >= cols) {
            if (dir == 1 || dir == 3) {
                dir = (dir + 2) % 4; // Change direction to left-right or right-up
            } else {
                dir = (dir + 1) % 4; // Change direction to up-right or down-left
            }
            x += dx[dir];
            y += dy[dir];
        } else {
            x = newX;
            y = newY;
        }
        ix++;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int row = 0, col = 0;
    int direction = 0; // 0 for right, 1 for down

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[row][col];

        if (direction == 0) {
            // Moving right
            if (col < cols - 1) {
                col++;
            } else {
                // If we reach the end in this row, move to the next row in the same diagonal
                row++;
            }
        } else {
            // Moving down
            if (row < rows - 1) {
                row++;
            } else {
                // If we reach the end in this column, move to the next column in the same diagonal
                col++;
            }
        }

        if (col == 0 || col == cols - 1 || row == 0 || row == rows - 1) {
            // Change direction if we reach an edge
            direction = 1 - direction;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int row = mat.length;
    int col = mat[0].length;
    int numElements = row * col;
    int[] result = new int[numElements];

    int curRow = 0;
    int curCol = 0;
    int dir = 1; // 1 for right down, -1 for left up

    for (int i = 0; i < numElements; i++) {
        result[i] = mat[curRow][curCol];

        int nextRow = curRow + dir;
        int nextCol = curCol + dir;

        if (nextRow < 0 || nextRow >= row || nextCol < 0 || nextCol >= col) {
            dir *= -1;
            nextRow += dir;
            nextCol += dir;
        }

        curRow = nextRow;
        curCol = nextCol;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    int i = 0; // Current row
    int j = 0; // Current column
    int count = 0; // Index for the result array

    // Traverse diagonals
    for (int k = 0; k < totalElements; k++) {
        result[count++] = mat[i][j];

        // Check if the next direction is valid
        if ((i == 0 && j < cols - 1) || (i + 1 < rows && j == 0)) {
            j++;
        } else if (i + 1 < rows && j < cols - 1) {
            i++;
        } else if (i == rows - 1) {
            i--;
            j++;
        } else if (j == cols - 1) {
            j--;
            i++;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0) {
            return new int[0]; // Return an empty array for invalid input
        }

        List<Integer> result = new ArrayList<>();
        int rows = mat.length;
        int cols = mat[0].length;
        int maxDiagonalSize = Math.max(rows, cols);

        for (int d = 0; d < maxDiagonalSize; d++) {
            List<Integer> currentDiagonal = new ArrayList<>();
            int i = Math.max(0, d);
            int j = Math.min(d, cols - 1);
            while (i < rows && j >= 0) {
                currentDiagonal.add(mat[i][j]);
                i++;
                j--;
            }
            result.addAll(currentDiagonal);
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }

public static int findSmallestInteger(int n) {
