}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 1;

    // Find the first decreasing digit from the right
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }

    if (i == 0) {
        return -1; // The digits are sorted in descending order, no rearrangement possible
    }

    // Find the smallest digit greater than digits[i-1] from the right
    int j = digits.length - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }

    // Swap digits[i-1] and digits[j]
    char temp = digits[i - 1];
    digits[i - 1] = digits[j];
    digits[j] = temp;

    // Sort the digits after i-1
    Arrays.sort(digits, i, digits.length);

    // Convert the array of characters back to an integer
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    // Convert the integer to an array of its digits
    char[] digits = String.valueOf(n).toCharArray();

    // Check each digit from the end of the array
    for (int i = digits.length - 2; i >= 0; i--) {
        // Find the smallest digit greater than the current digit, starting from the right
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[j] > digits[i]) {
                // Swap the two digits
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;

                // Sort the remaining digits in ascending order
                Arrays.sort(digits, i + 1);

                // Convert the array of digits back to an integer
                return Integer.parseInt(new String(digits));
            }
        }
    }
    // If no such rearrangement can be found, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    String str = Integer.toString(n);
    int len = str.length();
    if (len < 1) {
        return -1; // No digits, no possible rearrangement
    }

    int largestIndex = -1;
    int largestDigit = -1;

    // Find the largest digit and its index
    for (int i = len - 1; i >= 0; i--) {
        if (str.charAt(i) - '0' > largestDigit) {
            largestDigit = str.charAt(i) - '0';
            largestIndex = i;
        }
    }

    if (largestIndex == -1) {
        return -1; // No larger digit found
    }

    int smallestIndex = largestIndex + 1;
    while (smallestIndex < len && str.charAt(smallestIndex) - '0' <= largestDigit) {
        smallestIndex++;
    }

    if (smallestIndex == len) {
        return -1; // The remaining digits are non-increasing, no smaller numbers can be formed
    }

    // Swap the largest and smallest digits
    char temp = str.charAt(largestIndex);
    str = str.substring(0, largestIndex) + str.charAt(smallestIndex) + str.substring(largestIndex + 1);
    return Integer.parseInt(str);
}

public static int findSmallestInteger(int n) {
    String original = "" + n;
    char[] chars = original.toCharArray();
    do {
        char temp = chars[0];
        int idx = 1;
        for (; idx < chars.length; idx++) {
            if (chars[idx] < temp) {
                temp = chars[idx];
                idx++;
            }
        }
        if (idx < chars.length) {
            swap(chars, 0, idx - 1);
        } else {
            return -1; // No smaller integer can be formed
        }
        for (int i = idx; i < chars.length; i++) {
            if (chars[i] > temp) {
                swap(chars, idx, i);
                break;
            }
        }
        int result = 0;
        for (char c : chars) {
            result = result * 10 + (c - '0');
        }
        return result;
    } while (true); // Continue decreasing until a valid result is found
}

