public static List<String> centerSymmetricNumbers(int n) {
    List<String> results = new ArrayList<>();
    if (n <= 0) {
        return results;
    }

    // Check for even n or n equal to 1
    if (n % 2 == 0 || n == 1) {
        results.add(String.valueOf(0));
        return results;
    }

    // Determine the start and end base digits for generating center symmetric numbers
    int base = (int) Math.pow(10, (n - 1) / 2);
    int end = base * 10;

    // Generate a set of valid base digits
    Set<Integer> bases = new HashSet<>();
    for (int i = base; i <= end; i++) {
        int current = i;
        int reverse = 0;
        while (current > 0) {
            reverse *= 10;
            reverse += current % 10;
            current /= 10;
        }
        if (reverse == i) {
            bases.add(i);
        }
    }

    // Generate and add center symmetric numbers to the results list
    for (int base : bases) {
        String prefix = String.valueOf(base);
        String suffix = prefix.substring(0, prefix.length() - 1);
        results.add(prefix + suffix);
        results.add(prefix + new StringBuilder(suffix).reverse().toString());
    }

    return results;
}

public static List<String> centerSymmetricNumbers(int n) {
