        return centerSymmetricNumbers;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = Math.max(0, n - i), k = Math.min(n, i); j <= k; j++) {
            String num = String.valueOf(i);
            for (int s = 0; s <= j; s++) {
                num = "0" + num + '0';
            }
            for (int r = 0; r <= i - j - 1; r++) {
                num = "0" + num + '0';
            }
            centerSymmetricNumbers.add(num);
        }
    }
    return centerSymmetricNumbers;
}

