public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be greater than 0");
    }

    Set<Integer> uglySet = new LinkedHashSet<>();
    uglySet.add(1);

    while (uglySet.size() < n) {
        int nextUgly = Integer.MAX_VALUE;
        for (int ugly : uglySet) {
            nextUgly = Math.min(nextUgly, ugly * 2);
            nextUgly = Math.min(nextUgly, ugly * 3);
            nextUgly = Math.min(nextUgly, ugly * 5);
        }
        uglySet.add(nextUgly);
    }

    return uglySet.iterator().next();
}

