public static List<Integer> lexicalOrder(int n) {
        // Using a priority queue for a min-heap
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int i = 1; i <= 9; i++) {
            minHeap.offer(i);
        }

        List<Integer> result = new ArrayList<>();
        while (!minHeap.isEmpty()) {
            result.add(minHeap.poll());
            if (result.get(result.size() - 1) * 10 <= n) {
                for (int i = 0; i <= 9; i++) {
                    Integer next = result.get(result.size() - 1) * 10 + i;
                    if (next <= n) {
                        minHeap.offer(next);
                    }
                }
            }
        }

        return result;
    }

