public static int minPerfectSquareSum(int n) {
    int a = (int) Math.sqrt(n);
    int min = n;
    for (int i = a; i > 0; i--) {
        int j = (int) Math.sqrt(n - i * i);
        int tmp = j * j + i * i;
        if (min > tmp) {
            min = tmp;
        }
    }
    return min;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);

    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

