    for (int i = 1; i * i <= n; i++)
    {
        for (int j = i * i; j <= n; j++)
        {
            dp[j] = Math.min(dp[j], dp[j - i * i] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split("\\s+");
    StringBuilder reversedString = new StringBuilder();

    for (String word : words) {
        char[] chars = word.toCharArray();
        for (int i = chars.length - 1; i >= 0; i--) {
            reversedString.append(chars[i]);
        }
        reversedString.append(" ");
    }

    // Remove trailing space
    if (reversedString.length() > 0) {
        reversedString.setLength(reversedString.length() - 1);
    }

    return reversedString.toString();
}

public static String reverseWords(String s) {
    // Split the string into words
    String[] words = s.split(" ");
    // Reverse each word and store in a new array
    String[] reversedWords = new String[words.length];
    for (int i = 0; i < words.length; i++) {
        StringBuilder reversed = new StringBuilder(words[i]);
        reversed.reverse();
        reversedWords[i] = reversed.toString();
    }
    // Join the reversed words back into a single string
    return String.join(" ", reversedWords);
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}

public static String reverseWords(String s) {
        return Arrays.stream(s.split(" "))
                       .map(String::reverse)
                       .collect(Collectors.joining(" "));
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    StringBuilder reversed = new StringBuilder();
    int start = 0;
    int end = 0;

    while (end < s.length()) {
        if (s.charAt(end) == ' ') {
            if (start != end) {
                // Reverse the substring between start and end
                reversed.append(new String(s.substring(start, end).toCharArray(), 0, end - start).reverse());
            }
            reversed.append(' ');
            start = end + 1; // Move to the next word
        }
        end++;
    }

    // Reverse the substring between start and end
    if (start != end) {
        reversed.append(new String(s.substring(start, end).toCharArray(), 0, end - start).reverse());
    }

    return reversed.toString();
}
